const body = $input.first().json.body;

const required = ['nationality', 'destination_country', 'visa_type'];
const missing = required.filter(f => !body[f]);
if (missing.length) {
  return [{ json: { valid: false, error: `Missing: ${missing.join(', ')}` } }];
}

const validVisaTypes = [
  'tourist', 'business', 'student', 'work', 'digital_nomad',
  'family_reunion', 'transit', 'medical', 'retirement', 'investor'
];
const visaType = validVisaTypes.includes(body.visa_type) ? body.visa_type : 'tourist';

return [{
  json: {
    valid: true,
    nationality: body.nationality.trim(),
    destinationCountry: body.destination_country.trim(),
    visaType,
    purposeDetails: (body.purpose_details || '').slice(0, 600),
    intendedStayDays: parseInt(body.intended_stay_days) || null,
    departureDate: body.departure_date || '',
    currentResidence: body.current_residence || '',
    employmentStatus: body.employment_status || '',
    hasChildren: body.has_children === true || body.has_children === 'true',
    previousVisaRefusals: body.previous_visa_refusals === true || body.previous_visa_refusals === 'true',
    replyEmail: body.reply_email || null,
    requestedAt: new Date().toISOString()
  }
}];

const searchResult = $('Search Visa Requirements').first().json;
const input = $('Validate Input').first().json;

const autoAnswer = searchResult.answer || '';
const snippets = (searchResult.results || [])
  .map(r => `SOURCE: ${r.url}\n${r.title}\n${(r.content || r.snippet || '').slice(0, 500)}`)
  .join('\n\n');

return [{
  json: {
    input,
    researchContext: autoAnswer
      ? `Summary: ${autoAnswer}\n\nDetailed sources:\n${snippets}`
      : snippets || 'No web results found — using general knowledge only.',
    sourceUrls: (searchResult.results || []).map(r => r.url).filter(Boolean)
  }
}];

values.content:
Generate a visa document checklist for this applicant.

Applicant details:
- Nationality: {{ $json.input.nationality }}
- Destination: {{ $json.input.destinationCountry }}
- Visa type: {{ $json.input.visaType }}
- Purpose / additional context: {{ $json.input.purposeDetails || 'none provided' }}
- Intended stay: {{ $json.input.intendedStayDays ? $json.input.intendedStayDays + ' days' : 'not specified' }}
- Departure date: {{ $json.input.departureDate || 'not specified' }}
- Current residence: {{ $json.input.currentResidence || 'not specified' }}
- Employment status: {{ $json.input.employmentStatus || 'not specified' }}
- Travelling with children: {{ $json.input.hasChildren }}
- Previous visa refusals: {{ $json.input.previousVisaRefusals }}

Current web research on requirements:
{{ $json.researchContext }}

Generate the checklist as this JSON:
{
  "disclaimer": "one sentence only — that this is informational and they should verify with the official embassy or consulate",
  "summary": "2-3 sentences: what type of visa this is, approximate processing time if known, and where to apply (embassy, consulate, e-visa portal, visa on arrival, etc.)",
  "visa_free_or_on_arrival": true or false,
  "visa_free_note": "if visa_free_or_on_arrival is true: explain what that means exactly (e.g. 30 days visa on arrival, extend once, etc.). null otherwise.",
  "checklist": [
    {
      "category": "category name e.g. Identity Documents | Financial Evidence | Travel Documents | Accommodation Proof | Employment/Study Documents | Additional for Your Situation",
      "items": [
        {
          "document": "document name",
          "required": "always | usually | sometimes",
          "details": "specific practical details — how many copies, validity period, format, translation needed, what it must show, minimum balance if financial, etc.",
          "watch_out": "common mistake or thing people get wrong with this document — null if nothing notable"
        }
      ]
    }
  ],
  "timeline_advice": "practical advice on when to start gathering documents and submit — specific to this visa type and destination",
  "previous_refusal_note": {{ $json.input.previousVisaRefusals }} ? "specific advice for handling a previous refusal in this application" : null,
  "children_note": {{ $json.input.hasChildren }} ? "additional documents typically needed when travelling with or applying for children" : null,
  "official_sources": [
    {
      "name": "name of the official resource",
      "url": "official URL — embassy website, government portal, etc."
    }
  ],
  "top_tips": ["3-4 practical tips specific to this visa type and nationality combination that often make the difference"]
}

parameters.jsCode:
const raw = $input.first().json.text || $input.first().json.content?.[0]?.text || '';
let checklist;
try {
  checklist = JSON.parse(raw.replace(/```json|```/g, '').trim());
} catch(e) {
  return [{ json: { error: 'Parse error', raw } }];
}

const input = $('Validate Input').first().json;
checklist._replyEmail = input.replyEmail;
checklist._nationality = input.nationality;
checklist._destination = input.destinationCountry;
checklist._visaType = input.visaType;
checklist._sourceUrls = $('Merge Research').first().json.sourceUrls || [];

return [{ json: checklist }];

const c = $input.first().json;
function esc(s) { return String(s||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }

const requiredColor = {
  always:    { bg: '#fef2f2', color: '#b91c1c', label: 'Always required' },
  usually:   { bg: '#fffbeb', color: '#b45309', label: 'Usually required' },
  sometimes: { bg: '#f0f9ff', color: '#0369a1', label: 'Sometimes requested' }
};

const categoryBlocks = (c.checklist || []).map(cat => {
  const itemRows = (cat.items || []).map(item => {
    const rc = requiredColor[item.required] || requiredColor.sometimes;
    return `
    <div style="border:1px solid #e8e4df;border-radius:6px;margin-bottom:10px;overflow:hidden">
      <div style="background:#f8f7f5;padding:8px 14px;display:flex;justify-content:space-between;align-items:center">
        <strong style="font-size:14px;color:#1a1a1a">${esc(item.document)}</strong>
        <span style="background:${rc.bg};color:${rc.color};font-size:11px;font-weight:700;padding:2px 8px;border-radius:10px;white-space:nowrap">${esc(rc.label)}</span>
      </div>
      <div style="padding:10px 14px">
        <div style="font-size:13px;color:#444;line-height:1.6">${esc(item.details)}</div>
        ${item.watch_out ? `<div style="margin-top:8px;font-size:12px;color:#d97706;background:#fffbeb;padding:6px 10px;border-radius:4px">⚠ ${esc(item.watch_out)}</div>` : ''}
      </div>
    </div>`;
  }).join('');

  return `
  <div style="margin-bottom:22px">
    <div style="font-size:12px;font-weight:700;text-transform:uppercase;letter-spacing:0.5px;color:#888;margin-bottom:10px;padding-bottom:6px;border-bottom:2px solid #f0ece6">${esc(cat.category)}</div>
    ${itemRows}
  </div>`;
}).join('');

const officialLinks = (c.official_sources || []).map(s =>
  `<div style="font-size:13px;padding:5px 0"><a href="${esc(s.url)}" style="color:#1d4ed8">${esc(s.name)}</a></div>`
).join('');

const tipList = (c.top_tips || []).map((t, i) =>
  `<div style="font-size:14px;padding:8px 0;border-bottom:1px solid #e8f0fe;line-height:1.6"><span style="color:#1d4ed8;font-weight:700;margin-right:8px">${i+1}.</span>${esc(t)}</div>`
).join('');

const alwaysCount = (c.checklist || []).reduce((s, cat) => s + (cat.items||[]).filter(i => i.required === 'always').length, 0);
const totalCount = (c.checklist || []).reduce((s, cat) => s + (cat.items||[]).length, 0);

const html = `<!DOCTYPE html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"></head>
<body style="margin:0;padding:16px;background:#f5f3f0;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif;color:#1a1a1a">
<div style="max-width:680px;margin:0 auto">

  <div style="background:#1e3a5f;color:#fff;padding:22px 28px;border-radius:10px 10px 0 0">
    <div style="font-size:11px;text-transform:uppercase;letter-spacing:1px;color:#93b4d4;margin-bottom:6px">${esc(c._visaType.replace(/_/g,' '))} Visa Checklist</div>
    <div style="font-size:20px;font-weight:700">${esc(c._nationality)} → ${esc(c._destination)}</div>
    <div style="margin-top:6px;font-size:13px;color:#93b4d4">${alwaysCount} required documents · ${totalCount} total items</div>
  </div>

  <div style="background:#fef3c7;padding:12px 28px;border:1px solid #fde68a;font-size:13px;color:#92400e">
    ${esc(c.disclaimer)}
  </div>

  ${c.visa_free_or_on_arrival ? `<div style="background:#f0fdf4;padding:14px 28px;border:1px solid #bbf7d0">
    <div style="font-size:12px;font-weight:700;text-transform:uppercase;color:#15803d;letter-spacing:0.4px;margin-bottom:6px">✅ Visa-free / On arrival</div>
    <div style="font-size:14px;color:#166534;line-height:1.6">${esc(c.visa_free_note)}</div>
  </div>` : ''}

  <div style="background:#fff;padding:18px 28px;border:1px solid #eee;border-top:none">
    <div style="font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:0.5px;color:#888;margin-bottom:8px">Overview</div>
    <p style="font-size:14px;line-height:1.7;color:#333;margin:0">${esc(c.summary)}</p>
  </div>

  <div style="background:#fff;padding:20px 28px;border:1px solid #eee;border-top:3px solid #eee">
    ${categoryBlocks}
  </div>

  <div style="background:#eff6ff;padding:16px 28px;border:1px solid #bfdbfe">
    <div style="font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:0.5px;color:#1d4ed8;margin-bottom:10px">Top tips</div>
    ${tipList}
  </div>

  <div style="background:#fff;padding:16px 28px;border:1px solid #eee;border-top:3px solid #eee">
    <div style="font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:0.5px;color:#888;margin-bottom:8px">Timeline</div>
    <p style="font-size:14px;line-height:1.65;color:#555;margin:0">${esc(c.timeline_advice)}</p>
  </div>

  ${c.previous_refusal_note ? `<div style="background:#fef2f2;padding:14px 28px;border:1px solid #fecaca">
    <div style="font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:0.5px;color:#b91c1c;margin-bottom:8px">Previous refusal — what to do</div>
    <p style="font-size:14px;line-height:1.65;color:#7f1d1d;margin:0">${esc(c.previous_refusal_note)}</p>
  </div>` : ''}

  ${c.children_note ? `<div style="background:#f5f3ff;padding:14px 28px;border:1px solid #ddd6fe">
    <div style="font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:0.5px;color:#7c3aed;margin-bottom:8px">Travelling with children</div>
    <p style="font-size:14px;line-height:1.65;color:#4c1d95;margin:0">${esc(c.children_note)}</p>
  </div>` : ''}

  ${officialLinks ? `<div style="background:#fff;padding:14px 28px;border:1px solid #eee;border-top:3px solid #eee">
    <div style="font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:0.5px;color:#888;margin-bottom:8px">Official sources</div>
    ${officialLinks}
  </div>` : ''}

  <div style="background:#1e3a5f;color:#4a7fa5;font-size:11px;padding:12px 28px;border-radius:0 0 10px 10px;font-family:monospace;text-align:center">
    Visa Checklist Agent · Not official immigration advice · ${new Date().toLocaleDateString()}
  </div>
</div>
</body></html>`;

return [{ json: { html, replyEmail: c._replyEmail, nationality: c._nationality, destination: c._destination, visaType: c._visaType, checklist: c } }];
